create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.TMS_AUFTRAG_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH',
	SYSTEM_ID NUMBER(38,0) NOT NULL COMMENT 'Spezifiziert das Quellsystem, aus dem die Daten kommen.',
	TMS_AUFTRAG_ID VARCHAR(30) NOT NULL COMMENT 'ID des Auftrags (Auftragsnummer). Aus plau.au_nr',
	TMS_AUFTRAG_UNTER_ID NUMBER(38,0) NOT NULL COMMENT 'Auftragsunternummer zur Aufteilung eines Auftrages in Teillieferungen. Aus plau.au_unter_nr',
	TMS_AUFTRAG_LFD_NR NUMBER(38,0) NOT NULL COMMENT 'SKey für die Tabelle tms_auftrag_2 im Quellsystem. Aus plau.id_auftrag',
	LIEF_BELEG_ID NUMBER(38,0) COMMENT 'die Beleg ID des Lieferscheins',
	KJ_LIEF_BELEG NUMBER(38,0) COMMENT 'Kalenderjahr aus LFDAT. Lookup in besch_lief_2, -1 für keinen Treffer',
	VERSANDSTELLE_ID VARCHAR(4) COMMENT 'Versandstelle',
	TMS_SORTIMENT_ID NUMBER(38,0) COMMENT 'Artikelsortiment. IDs weichen teilw. von SAP ab!',
	LIEFERKUNDE_TMS_GP_ID VARCHAR(30) COMMENT 'ID des tms_gp_2, welcher hier als Lieferkunde auftrifft',
	LIEFERKUNDE_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Code für den tms_gp_2-Typ, welcher hier als Lieferkunde auftrifft',
	AUFTRAGSTEXT_1 VARCHAR(100) COMMENT 'Auftragstext, der kundenspezifisch verwendet wird',
	AUFTRAGSTEXT_2 VARCHAR(100) COMMENT 'Auftragstext, der kundenspezifisch verwendet wird',
	AUFTRAGSTEXT_3 VARCHAR(100) COMMENT 'Auftragstext, der kundenspezifisch verwendet wird',
	TMS_AUFTRAGSART_ID NUMBER(38,0) COMMENT 'Art_2 des Auftrags',
	BELADESTELLE_TMS_GP_ID VARCHAR(30) COMMENT 'ID des tms_gp_2, welcher hier als Beladestelle auftrifft',
	BELADESTELLE_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Code für den tms_gp_2-Typ, welcher hier als Beladestelle auftrifft',
	DAT_BEST DATE COMMENT 'Bestelldatum',
	EMPFAENGER_TMS_GP_ID VARCHAR(30) COMMENT 'ID des tms_gp_2, welcher hier als Empfänger auftrifft',
	EMPFAENGER_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Code für den tms_gp_2-Typ, welcher hier als Empfänger auftrifft',
	ENTLADESTELLE_TMS_GP_ID VARCHAR(30) COMMENT 'ID des tms_gp_2, welcher hier als Entladestelle auftrifft',
	ENTLADESTELLE_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Code für den tms_gp_2-Typ, welcher hier als Entladestelle auftrifft',
	QUELLSYSTEM_NAME VARCHAR(20) COMMENT 'Datenherkunft aus der Schnittstelle (z. B. EWM, LES)',
	LIEFERGEBIET_TXT VARCHAR(10) COMMENT 'Liefergebiet (Geographisch lassen sich Kunden in Gebiete ähnlich Postleitzahlengebieten einteilen)',
	TMS_LAND_CD VARCHAR(5) COMMENT 'Länderkennzeichen des Lieferkunden',
	TMS_LIEFERART_ID VARCHAR(3) COMMENT 'Art_2 der Lieferung; 0 = Normal, 1 = via CD, 2 = ???',
	DAT_LIEF DATE COMMENT 'Lieferdatum',
	PLAN_STATUS_CD VARCHAR(3) COMMENT 'Planungsstatus (z.B. ''H'' für hochgesetzt, ''T'' auf Tour_2)',
	SENDER_NAME VARCHAR(12) COMMENT 'Versender (kein TMS-GP_2 sondern z. B. ERP)',
	TMS_TOUR_ID NUMBER(38,0) COMMENT 'Tournummer',
	DAT_TOUR DATE COMMENT 'Tourdatum',
	TMS_TOUR_POS_ID NUMBER(38,0) COMMENT 'Entladetourposition, gibt die Reihenfolge an in der z. B. die Märkte angefahren werden sollen',
	VERSENDER_TMS_GP_ID VARCHAR(30) COMMENT 'ID des tms_gp_2, welcher hier als Versender auftrifft',
	VERSENDER_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Code für den tms_gp_2-Typ, welcher hier als Versender auftrifft',
	TEMPERATURGRUPPE_ID NUMBER(38,0) COMMENT 'Temperaturgruppe des Auftrags.  0 = Nicht gesetzt, 1 = TK (Tiefgekühlt), 2 = GK (Gekühlt), 3 = TE (Temperiert), 4 = UK (Ungekühlt), 5 = TB (Thermobehälter)',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	GEWICHT_BRUTTO_KG NUMBER(38,2) COMMENT 'Manuell erfasstes Frachtgewicht.',
	GEWICHT_NETTO_KG NUMBER(38,2) COMMENT 'Gesamt Gewicht des Auftrags.',
	ANZ_STELLPLATZ NUMBER(38,2) COMMENT 'Stücke / Einheiten an Stellplätzen des gesamten Auftrags.',
	VORHOLSPEDITION_TMS_GP_ID VARCHAR(30) COMMENT 'Geschäftspartner ID der Vorholspedition. Die Vorholspedition sammelt alles von den Beladestellen ein, ggf. an unterschiedlichen Adressen.',
	VORHOLSPEDITION_TMS_GP_TYP_CD VARCHAR(3) COMMENT 'Art_2 der Vorholspedition.',
	TMS_AUFTRAG_ORIG_ID VARCHAR(30) COMMENT 'Original Auftragsnummer inklusive aller Zeichen (alphanumerisch und Sonderzeichen), falls vorhanden.',
	BEST_BELEG_ID NUMBER(38,0) COMMENT 'ID des Bestellbelegs, bezieht sich auf in Wanko angelegte Aufträge.',
	TMS_AUFTRAG_STATUS_CD VARCHAR(20) COMMENT 'Status_2 der Auftragshostkommunikation: 10 = offen; 20 = in Bearbeitung; 30 = disponierbar; 40 = disponiert; 50 = avisiert; 60 = teilweise geliefert; 70 = geliefert; 99 = gelöscht.',
	constraint PK_TMS_AUFTRAG primary key (MANDANT_ID, SYSTEM_ID, TMS_AUFTRAG_ID, TMS_AUFTRAG_UNTER_ID)
)COMMENT='TMS - Die Tabelle enthält die relevanten Informationen zu einem Distributionsauftrag, einschließlich Auftragsart, Lieferdatum, Lieferkunde, entsprechende TMS-Tour_2-Detail-Bezeichnung und beteiligte Geschäftspartner. Aus Quelle plau (WANKO)'
;
